let existingUnit = ''; try { existingUnit = String($('Cek_user_status').first().json.unit_interest_db || ''); } catch (e) {}
let existingBudget = ''; try { existingBudget = String($('Cek_user_status').first().json.budget_range_db || ''); } catch (e) {}
