// sanitasi ringan: buang karakter kontrol (charCode < 32) tanpa escape unicode, rapikan spasi, batasi panjang.
const cleanProfile = s => String(s || '').split('').filter(ch => ch.charCodeAt(0) >= 32).join('').replace(/\s+/g, ' ').trim().slice(0, 60);
