const canonType = (s) => { const t = String(s); const m = t.match(/(\d{2,3})\s*\/\s*(\d{2,3})/); if (m) return `Tipe ${m[1]}/${m[2]}`; if (/komersil|komersial/i.test(t)) return 'Komersial'; if (/subsidi/i.test(t)) return 'Subsidi'; return null; };
